package com.example.payment.integrationtest.paymentgateway;

import static com.github.tomakehurst.wiremock.client.WireMock.aResponse;
import static com.github.tomakehurst.wiremock.client.WireMock.equalToJson;
import static com.github.tomakehurst.wiremock.client.WireMock.postRequestedFor;
import static com.github.tomakehurst.wiremock.client.WireMock.stubFor;
import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static com.github.tomakehurst.wiremock.client.WireMock.verify;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.github.tomakehurst.wiremock.junit5.WireMockExtension;
import java.math.BigDecimal;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.RegisterExtension;
import org.springframework.web.client.RestClient;

/**
 * Verifies the wire contract with the payment provider: the JSON we send on
 * POST /v1/authorizations, and the outcomes we derive from its answers,
 * including its 402 refusal.
 */
class HttpPaymentGatewayTest {

    @RegisterExtension
    static final WireMockExtension PROVIDER = WireMockExtension.newInstance().build();

    private HttpPaymentGateway sut;

    @BeforeEach
    void setUp() {
        var client = RestClient.builder().baseUrl(PROVIDER.baseUrl()).build();
        sut = new HttpPaymentGateway(client);
    }

    @Test
    void authorize_sendsReferenceAmountAndCurrencyAsJson() {
        stubFor(com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200)
                        .withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        sut.authorize("ORD-7", new Money(new BigDecimal("12.00"), "eur"));

        verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withRequestBody(equalToJson(
                        "{\"reference\":\"ORD-7\",\"amount\":12.00,\"currency\":\"EUR\"}", true, false)));
    }

    @Test
    void authorize_whenProviderApproves_returnsApproved() {
        stubFor(com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200)
                        .withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        var outcome = sut.authorize("ORD-7", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void authorize_whenProviderReturnsDeclinedStatus_returnsDeclined() {
        stubFor(com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200)
                        .withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"declined\"}")));

        var outcome = sut.authorize("ORD-8", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void authorize_whenProviderRefusesWith402_returnsDeclined() {
        stubFor(com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(402)));

        var outcome = sut.authorize("ORD-9", new Money(new BigDecimal("12.00"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void authorize_whenProviderAnswersWithAnUnexpectedError_throws() {
        stubFor(com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(() -> sut.authorize("ORD-10", new Money(new BigDecimal("12.00"), "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}
EOF
